/// <summary>
/// PaffH 06.10.21
/// Method transfered from Ax2009.Data Dictionary.Tables.KCS_LimitFactors
/// </summary>
/// <returns>boolean</returns>
boolean checkItemRelation()
{
    boolean  ok = true;
    ;

    switch(this.ItemCode)
    {
        case TableGroupAll::Table       :   
            if (! InventTable::exist(this.ItemRelation))
            {
                ok = checkFailed("@SYS17075");
            }
            break;

        case TableGroupAll::GroupId     :   
            if (! KCS_GoodsGroup::exist(this.ItemRelation))
            {
                ok = checkFailed("@SYS17075");
            }
            break;

        case TableGroupAll::All         :   
            if (this.ItemRelation)
            {
                ok = checkFailed("@SYS17075");
            }
            break;
    }
    return ok;
}

