}

/// <summary>
/// PaffH 06.10.21
/// Method transfered from Ax2009.Data Dictionary.Tables.KCS_LimitFactors
/// </summary>
/// <param name = "_fieldId">fieldId</param>
/// <returns>boolean</returns>
boolean  validateField(fieldId  _fieldId)
{
    boolean ret = super(_fieldId);

    switch(_fieldId)
    {
        case(fieldnum(KCS_LimitFactors, ItemRelation)) : 
            ret = this.checkItemRelation();
            break;
    }

    return ret;
}

/// <summary>
/// PaffH 06.10.21
/// Method transfered from Ax2009.Data Dictionary.Tables.KCS_LimitFactors
/// </summary>
/// <returns>boolean</returns>
boolean validateWrite()
{
    boolean ret = super();

