/// <summary>
/// PaffH 06.10.21
/// Method transfered from Ax2009.Data Dictionary.Tables.KCS_LimitFactors
/// </summary>
/// <param name = "_groupName">KCS_GroupNameBase</param>
/// <param name = "_itemCode">KCS_LimitFactorItemCode</param>
/// <param name = "_itemRelation">KCS_LimitFactorItemRelation</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>KCS_LimitFactors</returns>
public static KCS_LimitFactors find(KCS_GroupNameBase       _groupName,
                                KCS_LimitFactorItemCode     _itemCode,
                                KCS_LimitFactorItemRelation _itemRelation,
                                boolean                     _forUpdate = false)
{
    KCS_LimitFactors record;

    record.selectForUpdate(_forUpdate);

    if(_groupName && _itemCode && _itemRelation)
    {
        select firstonly record
        where record.GroupName            == _groupName    &&
              record.ItemCode             == _itemCode     &&
              record.ItemRelation         == _itemRelation;
    }
    return record;
}
